std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::collapse_edge(EdgeRef e) {
	HalfedgeRef h = e->halfedge;
	HalfedgeRef t = h->twin;
	VertexRef a = h->vertex;   // h: a -> b
	VertexRef b = t->vertex;
	FaceRef f = h->face;
	FaceRef g = t->face;

	//--- validity checks ---
	// endpoints both on boundary but edge not on boundary -> would pinch boundary
	if (a->on_boundary() && b->on_boundary() && !e->on_boundary()) return std::nullopt;

	// common neighbor check:
	// collect tips of triangular faces adjacent to e:
	std::unordered_set<VertexRef> tips;
	if (!f->boundary && h->next->next->next == h) tips.insert(h->next->next->vertex);
	if (!g->boundary && t->next->next->next == t) tips.insert(t->next->next->vertex);

	// neighbors of a:
	std::unordered_set<VertexRef> nbrs_a;
	{
		HalfedgeRef x = a->halfedge;
		do {
			nbrs_a.insert(x->twin->vertex);
			x = x->twin->next;
		} while (x != a->halfedge);
	}
	// any common neighbor of a and b that is not a tip -> non-manifold result
	{
		HalfedgeRef x = b->halfedge;
		do {
			VertexRef n = x->twin->vertex;
			if (n != a && nbrs_a.count(n) && !tips.count(n)) return std::nullopt;
			x = x->twin->next;
		} while (x != b->halfedge);
