	//A2L1: Flip Edge - works for general polygon faces

	//Phase 0: collect elements.
	//
	//  f: ... pa -> h:[a -> b] -> bn:[b -> c] -> rest ...
	//  g: ... pb -> t:[b -> a] -> an:[a -> d] -> rest ...
	//
	HalfedgeRef h = e->halfedge;
	HalfedgeRef t = h->twin;
	if (h->face->boundary || t->face->boundary) return std::nullopt;

	FaceRef f = h->face;
	FaceRef g = t->face;
	VertexRef a = h->vertex;
	VertexRef b = t->vertex;

	HalfedgeRef bn = h->next;         //[b -> c] on f
	HalfedgeRef rest_f = bn->next;    //starts at c, on f
	VertexRef c = rest_f->vertex;

	HalfedgeRef an = t->next;         //[a -> d] on g
	HalfedgeRef rest_g = an->next;    //starts at d, on g
	VertexRef d = rest_g->vertex;

	//halfedges before h and t:
	HalfedgeRef pa = rest_f;
	while (pa->next != h) pa = pa->next;
	HalfedgeRef pb = rest_g;
	while (pb->next != t) pb = pb->next;

	//Phase 1: validity checks -- would the flipped edge create an invalid mesh?

