args.new_string:
std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::collapse_edge(EdgeRef e) {
	//A2L3: Collapse Edge - general polygon version

	//Phase 0: collect elements.
	//
	//  f: ... -> h:[a -> b] -> ...   (face on h's side)
	//  g: ... -> t:[b -> a] -> ...   (face on t's side)
	//
	HalfedgeRef h = e->halfedge;
	HalfedgeRef t = h->twin;
	VertexRef a = h->vertex;
	VertexRef b = t->vertex;
	FaceRef f = h->face;
	FaceRef g = t->face;

	bool f_tri = (h->next->next->next == h); //f degenerates to an edge
	bool g_tri = (t->next->next->next == t); //g degenerates to an edge

	//Phase 1: validity checks -- reject collapses that would break manifoldness.

	//collapsing a non-boundary edge whose endpoints are both on the boundary
	// would pinch the boundary into two loops sharing a single vertex:
	if (!e->on_boundary() && a->on_boundary() && b->on_boundary()) return std::nullopt;

	//the "tips" of triangular faces adjacent to e: these common neighbors of
	// a and b merge away cleanly when their faces degenerate:
	std::unordered_set<VertexRef> tips;
	if (f_tri) tips.insert(h->next->next->vertex);
	if (g_tri) tips.insert(t->next->next->vertex);

	//if both adjacent faces are triangles with the *same* tip, they share all
	// three edges and collapsing would tangle the resulting merges:
	if (f_tri && g_tri && h->next->next->vertex == t->next->next->vertex) return std::nullopt;

	//any common neighbor of a and b other than a triangle tip would end up
	// connected to the collapsed vertex by two distinct edges (non-manifold):
	{
		std::unordered_set<VertexRef> nbrs;
		HalfedgeRef x = a->halfedge;
		do {
			nbrs.insert(x->twin->vertex);
			x = x->twin->next;
		} while (x != a->halfedge);
		x = b->halfedge;
		do {
			VertexRef n = x->twin->vertex;
			if (n != a && nbrs.count(n) && !tips.count(n)) return std::nullopt;
			x = x->twin->next;
		} while (x != b->halfedge);
	}

	//Phase 2: collapse!
	//merge endpoint data into a and move it to the middle of the edge:
	a->position = e->center();
	interpolate_data({a, b}, a); //bone weights, etc.

	//every halfedge that started at b now starts at a:
	{
		HalfedgeRef x = t;
		do {
			HalfedgeRef nxt = x->twin->next;
			x->vertex = a;
			x = nxt;
		} while (x != t);
	}

	//remove e's halfedge h from f, merging edges if f degenerates:
	if (f_tri) {
		//f is a triangle; removing e leaves two coincident edges -- merge them:
		HalfedgeRef h1 = h->next;   //[b -> c] (now [a -> c])
		HalfedgeRef h2 = h1->next;  //[c -> a]
		HalfedgeRef h1t = h1->twin; //[c -> b] (kept; becomes [c -> a])
		HalfedgeRef h2t = h2->twin; //[a -> c] (kept)
		VertexRef c = h2->vertex;
		EdgeRef e1 = h1->edge;
		EdgeRef e2 = h2->edge;

		//merge corner data of the halfedge pairs that are being unified:
		interpolate_data({h1t, h2}, h1t); //corner at c
		interpolate_data({h2t, h1}, h2t); //corner at a

		h1t->twin = h2t;
		h2t->twin = h1t;
		e2->halfedge = h2t;
		h2t->edge = e2;
		h1t->edge = e2;

		if (c->halfedge == h2) c->halfedge = h1t;
		if (a->halfedge == h) a->halfedge = h2t;

		erase_halfedge(h1);
		erase_halfedge(h2);
		erase_edge(e1);
		erase_face(f);
	} else {
		//f is a polygon; splice h out of its loop:
		HalfedgeRef hp = h->next;
		while (hp->next != h) hp = hp->next;
		hp->next = h->next;
		f->halfedge = h->next;
		if (a->halfedge == h) a->halfedge = h->next;
	}

	//same for t and g:
	if (g_tri) {
		HalfedgeRef t1 = t->next;   //[a -> d]
		HalfedgeRef t2 = t1->next;  //[d -> b] (now [d -> a])
		HalfedgeRef t1t = t1->twin; //[d -> a] (kept)
		HalfedgeRef t2t = t2->twin; //[b -> d] (kept; now [a -> d])
		VertexRef d = t2->vertex;
		EdgeRef e1 = t1->edge;
		EdgeRef e2 = t2->edge;

		interpolate_data({t1t, t2}, t1t); //corner at d
		interpolate_data({t2t, t1}, t2t); //corner at a

		t1t->twin = t2t;
		t2t->twin = t1t;
		e1->halfedge = t1t;
		t1t->edge = e1;
		t2t->edge = e1;

		if (d->halfedge == t2) d->halfedge = t1t;
		if (a->halfedge == t1) a->halfedge = t2t;

		erase_halfedge(t1);
		erase_halfedge(t2);
		erase_edge(e2);
		erase_face(g);
	} else {
		HalfedgeRef tp = t->next;
		while (tp->next != t) tp = tp->next;
		tp->next = t->next;
		g->halfedge = t->next;
		//(a->halfedge can't be t -- t started at b)
	}

	//finally, remove the collapsed edge and the absorbed vertex:
	erase_halfedge(h);
	erase_halfedge(t);
	erase_edge(e);
	erase_vertex(b);

	return a;
}

