args.new_string:
void Halfedge_Mesh::extrude_positions(FaceRef face, Vec3 move, float shrink) {
	//A2L4h: Extrude Positions Helper

	//face is the inner face created by extrude_face(); each of its vertices w
	// was copied from an original vertex v, reachable as h->twin->next->twin->vertex
	// (out along the spoke of the surrounding side quads). The original vertices
	// are never moved by the extrusion, so they serve as absolute starting
	// positions -- this keeps repeated calls from compounding.

	//centroid of the original positions:
	Vec3 center(0.0f, 0.0f, 0.0f);
	uint32_t n = 0;
	{
		HalfedgeRef h = face->halfedge;
		do {
			center += h->twin->next->twin->vertex->position;
			++n;
			h = h->next;
		} while (h != face->halfedge);
	}
	center /= float(n);

	//push each inset vertex from its starting position toward the centroid by
	// `shrink`, then translate by `move`:
	HalfedgeRef h = face->halfedge;
	do {
		Vec3 start = h->twin->next->twin->vertex->position;
		h->vertex->position = center + (start - center) * (1.0f - shrink) + move;
		h = h->next;
	} while (h != face->halfedge);
}

