//A2G3: Catmull-Clark Subdivision

// This routine should end up looking a lot like linear_subdivide
// above, with the exception that the positions are a bit trickier
// to compute.

//Overview of the rules:
// https://en.wikipedia.org/wiki/Catmull%E2%80%93Clark_subdivision_surface

// Faces: new face vertices go at the centroid of the face:
for (FaceCRef f = faces.begin(); f != faces.end(); ++f) {
	if (!f->boundary) face_vertex_positions[f] = f->center();
}

// Edges: new edge vertices go at the average of the edge's endpoints and
// the (up to) two adjacent non-boundary face points; edges with a boundary
// side just use their midpoint:
for (EdgeCRef e = edges.begin(); e != edges.end(); ++e) {
	HalfedgeCRef h = e->halfedge;
	Vec3 sum = h->vertex->position + h->twin->vertex->position;
	if (!h->face->boundary && !h->twin->face->boundary) {
		sum += face_vertex_positions[h->face] + face_vertex_positions[h->twin->face];
		edge_vertex_positions[e] = sum / 4.0f;
	} else {
		edge_vertex_positions[e] = sum / 2.0f;
	}
}

// Vertices: interior vertices use the Catmull-Clark rule
//   (Q + 2R + (n-3)S) / n
// with Q the average of adjacent face points, R the average of incident
// edge midpoints, S the original position, and n the vertex degree.
// Boundary vertices use the boundary rule (6S + A + B) / 8, where A and B
// are the two neighbors along the boundary:
for (VertexCRef v = vertices.begin(); v != vertices.end(); ++v) {
	if (v->on_boundary()) {
		Vec3 sum = 6.0f * v->position;
		uint32_t found = 0;
		HalfedgeCRef h = v->halfedge;
		do {
			//h is on a boundary loop, or its twin is (then h->twin leaves
			// the neighbor and arrives at v along the boundary):
			if (h->face->boundary || h->twin->face->boundary) {
				sum += h->twin->vertex->position;
				++found;
			}
			h = h->twin->next;
		} while (h != v->halfedge);
		if (found == 2) {
			vertex_positions[v] = sum / 8.0f;
		} else {
			vertex_positions[v] = v->position; //shouldn't happen on a valid mesh
		}
	} else {
		Vec3 Q(0.0f, 0.0f, 0.0f);
		Vec3 R(0.0f, 0.0f, 0.0f);
		uint32_t n = 0;
		HalfedgeCRef h = v->halfedge;
		do {
			Q += face_vertex_positions[h->face];
			R += h->edge->center();
			++n;
			h = h->twin->next;
		} while (h != v->halfedge);
		Q /= float(n);
		R /= float(n);
		vertex_positions[v] = (Q + 2.0f * R + (float(n) - 3.0f) * v->position) / float(n);
	}
}

	) {

	//Phase 0: snapshot the original elements (the ones the position maps refer to):
	std::vector<EdgeRef> orig_edges(edges.begin(), edges.end());
	std::vector<VertexRef> orig_vertices(vertices.begin(), vertices.end());
	std::vector<FaceRef> orig_faces;
	for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
		if (!f->boundary) orig_faces.push_back(f);
	}
	std::unordered_set<VertexRef> orig_vertex_set(orig_vertices.begin(), orig_vertices.end());

	//Phase 1: bisect every edge of the original mesh, remembering which vertex
	// was created for each edge:
	std::unordered_map<EdgeCRef, VertexRef> edge_vertices;
	for (EdgeRef e : orig_edges) {
		if (std::optional<VertexRef> vm = bisect_edge(e)) {
			edge_vertices[e] = *vm;
		}
	}

	//Phase 2: split every original non-boundary face into quads around a newly
	// inserted center vertex. After the bisections, each such face looks like:
	//   [v0, m0, v1, m1, ..., v_{n-1}, m_{n-1}]
	// where the v_i are original vertices and the m_i are edge-bisection
	// vertices. Quad i becomes [v_i, m_i, c, m_{i-1}] for center vertex c.
	for (FaceRef f : orig_faces) {
		uint32_t n = f->degree() / 2;

		//collect the loop halfedges: A[i]: [v_i -> m_i], B[i]: [m_i -> v_{i+1}]
		std::vector<HalfedgeRef> A(n), B(n);
		{
			HalfedgeRef h = f->halfedge;
			while (!orig_vertex_set.count(h->vertex)) h = h->next;
			for (uint32_t i = 0; i < n; ++i) {
				A[i] = h;
				h = h->next;
				B[i] = h;
				h = h->next;
			}
		}

		//new center vertex:
		VertexRef c = emplace_vertex();
		if (auto it = face_vertex_positions.find(f); it != face_vertex_positions.end()) {
			c->position = it->second;
		} else {
			c->position = f->center();
		}
		{
			std::vector<VertexCRef> from;
			from.reserve(n);
			for (uint32_t i = 0; i < n; ++i) from.push_back(A[i]->vertex);
			interpolate_data(from, c);
		}

		//new spoke halfedges: p[i]: [m_i -> c], r[i]: [c -> m_{i-1}]
		//new spoke edges: pe[i]: [m_i -- c]
		std::vector<HalfedgeRef> p(n), r(n);
		std::vector<EdgeRef> pe(n);
		for (uint32_t i = 0; i < n; ++i) {
			p[i] = emplace_halfedge();
			r[i] = emplace_halfedge();
			pe[i] = emplace_edge(false);
		}

		//corner data for the new halfedges:
		for (uint32_t i = 0; i < n; ++i) {
			interpolate_data({B[i]}, p[i]); //corner at m_i
		}
		{
			std::vector<HalfedgeCRef> from;
			from.reserve(2 * n);
			for (uint32_t i = 0; i < n; ++i) {
				from.push_back(A[i]);
				from.push_back(B[i]);
			}
			for (uint32_t i = 0; i < n; ++i) {
				interpolate_data(from, r[i]); //corner at c
			}
		}

		//rewire: quad i = A[i]:[v_i -> m_i], p[i]:[m_i -> c], r[i]:[c -> m_{i-1}], B[i-1]:[m_{i-1} -> v_i]
		for (uint32_t i = 0; i < n; ++i) {
			uint32_t prev = (i + n - 1) % n;
			uint32_t next = (i + 1) % n;
			FaceRef q = (i == 0 ? f : emplace_face(false)); //reuse f for the first quad

			A[i]->next = p[i];
			A[i]->face = q;
			p[i]->set_tnvef(r[next], r[i], B[i]->vertex, pe[i], q);
			r[i]->set_tnvef(p[prev], B[prev], c, pe[prev], q);
			B[prev]->next = A[i];
			B[prev]->face = q;
			pe[i]->halfedge = p[i];
			q->halfedge = A[i];
		}
		c->halfedge = r[0];
	}

	//Phase 3: assign positions from the parameter maps.
	for (VertexRef v : orig_vertices) {
		if (auto it = vertex_positions.find(v); it != vertex_positions.end()) {
			v->position = it->second;
		}
	}
	for (EdgeRef e : orig_edges) {
		if (auto it = edge_vertex_positions.find(e); it != edge_vertex_positions.end()) {
			edge_vertices[e]->position = it->second;
		}
	}
}

